        });
        const tipId = tipMsg?.id?._serialized || tipMsg?.id?.$1 || tipMsg?.id?.id;
        if (tipId) ChatSessions.trackMessage(session.id, 'system_to_desk', tipId, tip);
        const tipChat = tipMsg?._outboundChatId || this.whatsapp._lastOutboundChatId;
